def exact_rank(rows: Sequence[Sequence[int]]) -> int:
    a = [[Fraction(x) for x in row] for row in rows]
    if not a:
        return 0
    r = 0
    for c in range(len(a[0])):
        pivot = next((i for i in range(r, len(a)) if a[i][c]), None)
        if pivot is None:
            continue
        a[r], a[pivot] = a[pivot], a[r]
        q = a[r][c]
        a[r] = [x / q for x in a[r]]
        for i in range(len(a)):
            if i != r and a[i][c]:
                q = a[i][c]
                a[i] = [x - q*y for x, y in zip(a[i], a[r])]
        r += 1
    return r

def is_rigid(rows: Sequence[Sequence[int]]) -> bool:
    return bool(rows) and exact_rank(rows) == len(rows[0])

if __name__ == "__main__":
    matrices = [[[1, 2], [0, 3], [4, -1]],
                [[1, 2, 3], [2, 4, 6], [-1, -2, -3]]]
    for matrix in matrices:
        print({"rank": exact_rank(matrix), "rigid": is_rigid(matrix)})

