def determinant(a: Sequence[Sequence[int]]) -> Fraction:
    m = [[Fraction(x) for x in row] for row in a]
    n = len(m); result = Fraction(1)
    for c in range(n):
        p = next((i for i in range(c,n) if m[i][c]), None)
        if p is None: return Fraction(0)
        if p != c: m[c],m[p]=m[p],m[c]; result=-result
        q=m[c][c]; result*=q
        for i in range(c+1,n):
            f=m[i][c]/q
            for j in range(c+1,n): m[i][j]-=f*m[c][j]
    return result

def maximal_minors(a: Sequence[Sequence[int]]) -> list[Fraction]:
    columns = len(a[0])
    return [determinant([a[i] for i in rows])
            for rows in combinations(range(len(a)), columns)]

from __future__ import annotations
from fractions import Fraction
from typing import Sequence

def scalar_extension_certificate(rows: Sequence[Sequence[int]]) -> tuple[int, int]:
    """Return a nonzero full-column minor and its row index in a small example."""
    a = [[Fraction(x) for x in row] for row in rows]
    if len(a[0]) != 2:
        raise ValueError("this compact demonstration expects two columns")
    for i in range(len(a)):
        for j in range(i+1, len(a)):
            det = a[i][0]*a[j][1] - a[i][1]*a[j][0]
            if det:
                return i, j
    raise ValueError("no full-column minor; the map is not rigid")

